const projects={flow:{title:'Flow',description:'A productivity workspace concept that puts clarity first. Organize tasks into simple boards, see what is in progress, and give your ideas a little breathing room.',tags:['React','TypeScript','Tailwind CSS']},sprout:{title:'Sprout',description:'A plant shop concept built around a warm, approachable shopping experience. Editorial typography and a nature-inspired palette help the products feel right at home.',tags:['Next.js','React','Framer Motion']},palette:{title:'Palette',description:'An exploration of color and creative tools. A compact palette interface for discovering unexpected combinations and finding a starting point for your next design.',tags:['JavaScript','CSS','Color theory']}};
const dialog=document.getElementById('project-dialog');
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const project=projects[button.dataset.project];document.getElementById('dialog-title').textContent=project.title;document.getElementById('dialog-description').textContent=project.description;document.getElementById('dialog-tags').replaceChildren(...project.tags.map(tag=>{const span=document.createElement('span');span.textContent=tag;return span}));dialog.showModal()}));
document.querySelector('.close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
